    'uc.hospitality.custom.0.title': `Kasse`,
    'uc.hospitality.custom.0.body':  `In Österreich gilt die Registrierkassenpflicht. Wie sich Ihre bestehende Kasse anbinden lässt, klären wir im ersten Gespräch.`,
    'uc.hospitality.custom.1.title': `Tischreservierung`,
